# Six paragraphs follow the supplied Essai A framework; genre adaptation is outside that shared body.
def essai(p,suffix):
 stance=stances.get(suffix,"Je défends une démarche progressive, qui prenne au sérieux les bénéfices possibles sans négliger les personnes et les contraintes concrètes.")
 benefit=p['benefit'];l1=p['limit1'];l2=p['limit2'];example=p['example'];collective=p['collective']
 # These tasks require a different emphasis from the otherwise shared topic profile.
 if suffix=='2022-6-cn':l1="les résultats dépendent des tâches étudiées et des profils linguistiques comparés";l2="un biais de publication peut rendre les résultats positifs plus visibles que les résultats négatifs";collective="présenter les limites méthodologiques et publier aussi les résultats qui contredisent les attentes"
 if suffix=='2021-3-cn':benefit="les associations rendent visibles des souffrances qui resteraient autrement peu connues";l1="certaines campagnes peuvent simplifier des situations culturelles ou économiques complexes";l2="une accusation générale contre toutes les associations empêche de distinguer leurs pratiques et leurs résultats";example="une association pourrait travailler avec des éleveurs pour améliorer les conditions des animaux tout en accompagnant les contraintes du métier"
 if suffix=='2021-5-cn':benefit="Internet peut réduire le coût d'une mobilisation et rendre des documents plus accessibles";l1="une pétition très partagée ne garantit ni une délibération éclairée ni un changement réel";l2="la manipulation de l'information et l'exclusion numérique peuvent fragiliser la participation"
 if suffix=='2024-3-fr':example="le site municipal pourrait proposer le prêt d'une perceuse, un échange de compétences et le don d'un meuble, avec des règles de sécurité et une aide en mairie pour les personnes peu à l'aise en ligne";collective="créer ce service municipal, expliquer les responsabilités et prévoir un accès hors ligne"
 paras=[f"La question {de(p['theme'])} suscite de vifs débats. Pour certains, une nouvelle orientation répond à une nécessité ; pour d'autres, elle risque d'aggraver des difficultés existantes. Faut-il pour autant trancher sans examiner ses effets ? {stance}",f"Certes, un argument mérite d'être reconnu : {benefit}. Dans la mesure où les personnes rencontrent des besoins réels, cette possibilité ne peut être ignorée. Il serait injuste de nier les attentes auxquelles elle cherche à répondre.",f"Toutefois, cet avantage ne saurait masquer plusieurs limites. D'une part, {l1}. D'autre part, {l2}. Même si un résultat semble favorable à court terme, rien ne garantit qu'il le demeure sans accompagnement. Une réponse générale peut déplacer le problème plutôt que le résoudre.",f"Le véritable enjeu consiste donc à définir une réponse adaptée aux situations. Cela suppose, en premier lieu, de {collective}. Il importe également d'associer les personnes concernées aux décisions, afin que les bénéfices ne se réalisent pas au détriment de l'équité. L'information doit être claire et les responsabilités identifiables.",f"Prenons un exemple concret : {example}. Une telle démarche permettrait de relier un objectif général à des conditions observables. Encore faut-il qu'elle soit évaluée régulièrement et ajustée selon les difficultés signalées, au lieu de confondre son lancement avec sa réussite.",f"En définitive, une réponse durable exige des choix explicites et des moyens cohérents. {stance} C'est en tenant compte des différences de situation que l'on pourra concilier les besoins individuels et l'intérêt collectif, sans se satisfaire d'une solution seulement séduisante en apparence."]
 if suffix in ['2021-10-fr','2024-11-cn','2025-6-cn']:
  sal='Madame, Monsieur,' if suffix=='2021-10-fr' else 'Madame la Maire,'
  purpose={'2021-10-fr':"Par cette lettre ouverte, je souhaite vous faire part de mon soutien à l'allongement du congé de paternité dans notre entreprise.",'2024-11-cn':"Je me permets de vous écrire pour m'opposer à l'expérimentation publicitaire envisagée sur nos trottoirs.",'2025-6-cn':"Je me permets de vous écrire au sujet de l'interdiction des véhicules motorisés dans le centre-ville pendant la journée."}[suffix]
  paras[0]=purpose+' '+paras[0];return para(sal)+''.join(para(x) for x in paras)+para('Je vous remercie de l’attention portée à cette demande. Veuillez agréer, '+sal.rstrip(',')+", l’expression de ma considération distinguée.")
 if suffix in ['2024-5-fr','2025-8-fr','2022-6-cn']:
  paras[0]="À la rédaction, je souhaite apporter la contribution suivante au débat. "+paras[0]
 return h('Quelle réponse aux enjeux actuels ?')+''.join(para(x) for x in paras)

notes={}
for line in (ROOT/'data/synthese-notes.tsv').read_text().splitlines():
 if line and not line.startswith('#'):
  id,*fields=line.split('|');notes[id]=fields

def synthesis(id):
 a,b,c,d=notes[id]
 texts=[f"Les documents s'intéressent {preposition_a(a)}. Ils abordent une même question sous des angles complémentaires ou contrastés. Leur rapprochement permet de dégager les principaux enjeux et les limites des réponses présentées.",f"Un premier constat se dégage des informations réunies. {b} Ces éléments éclairent les pratiques décrites et les attentes auxquelles elles se rattachent.",f"Cette première lecture demande toutefois à être précisée. {c} Les différences de perspective permettent ainsi de mieux comprendre la complexité du sujet, sans réduire le dossier à une seule explication.",f"L'ensemble fait donc apparaître un enjeu qui dépasse les exemples particuliers. {d}"]
 n=count(' '.join(texts))
 # Neutral bridges contain no new fact or recommendation.
 if n<200:texts[2]+=" Il convient ainsi de distinguer les constats exposés des interprétations qui leur sont associées."
 if count(' '.join(texts))>240:texts[1]=texts[1].replace(' Ces éléments éclairent les pratiques décrites et les attentes auxquelles elles se rattachent.','')
 return ''.join(para(x) for x in texts)

